from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'english','out-in-the-garden','Out in the Garden',
 ('Playing outside','A cheerful poem describes children playing in the garden on a fine day. They bounce, throw and catch a ball, tug, pull and fly a kite, and run, skip, jump, sway, slide and swing with friends. In this chapter you will learn new action words, use the joining word and, and make a paper bag puppet.'),
 [('What the children do in the garden',['The poem is about children playing in the garden on every fine day.','With a ball, they bounce it, throw it and catch it.','With a kite, they tug it, pull it and fly it.','With friends, they run, skip, jump, sway, slide and swing.','Playing outdoors keeps us healthy and happy, but we must be careful so that we do not get hurt.']),
  ('New words from the poem',['Bounce means to spring back up after hitting the ground, as a ball does.','Throw means to send something through the air with your hand.','Sway means to move slowly from side to side, like a branch in the wind.','Slide means to move smoothly over a surface, like on a playground slide.']),
  ('Joining words with and',['The poem has pairs such as run and skip, jump and sway, and slide and swing.','The word and joins two words that go together.','Give and take, sing and dance, eat and drink, catch and throw, run and catch are more pairs joined by and.','We can think of our own pairs, such as read and write or sit and stand.']),
  ('Games we play',['Children play many games, and the same game can have a different name in our mother tongue.','When playing, we should take turns, play fairly and take care of ourselves and our friends.']),
  ('Make a paper bag puppet',['You need a paper bag, a pencil, colour pencils or sketch pens, woollen thread and gum.','Fold the base of the bag upward and hold it upside down. Draw the upper lip on the flap and the lower lip just below it, then draw a face and colour it.','Slide your hand inside and bend your fingers, and the puppet can talk.'])],
 [('Join the words give, take with and.',[('Take the two words.','Give and take.'),('Put the word and between them.','It joins the two words.'),('Give and take is the pair.','The same works for sing and dance.')]),
  ('What happens to a kite in the poem?',[('The children tug and pull it.','These are actions.'),('Then they fly it.','The kite goes up in the sky.'),('They do this on each fine day.','It is a regular happy game.')])],
 ('Tell what the children do with a ball and a kite.',['Ball: bounce, throw, catch','Kite: tug, pull, fly','Joined by and'],['They play in the classroom','They eat the ball']),
 ['Children play with a ball, a kite and friends.','Bounce, throw, sway and slide are action words.','The word and joins two words.','Be careful when playing outside.','A paper bag can be made into a puppet.'],
 [M('1',1,'Where are the children playing?','In the garden',[('In the kitchen','The poem says garden'),('In the school hall','The poem says garden')],'They play out in the garden.'),
  M('2',1,'What do the children do with the kite?','Tug, pull and fly it',[('Eat it','Not in the poem'),('Wash it','Not in the poem')],'They tug, pull and fly the kite.'),
  M('3',1,'Which word joins two words?','and',[('the','The does not join'),('is','Is does not join')],'And joins two words.'),
  M('4',1,'What can children do with a ball?','Bounce, throw and catch it',[('Fly it','A kite is flown'),('Sing it','Not in the poem')],'They bounce, throw and catch the ball.'),
  M('5',2,'Which is the pair using and?','Run and catch',[('Run catch','Missing and'),('And run catch','Wrong order')],'Run and catch.'),
  M('6',2,'What does bounce mean?','To spring back up after hitting the ground',[('To sleep','Not the meaning'),('To cut','Not the meaning')],'A ball bounces back up.'),
  F('7',2,'Children should be careful while playing outside.',True,'Careless play can hurt us.'),
  M('8',2,'Which word means to move from side to side?','Sway',[('Throw','Throw sends something'),('Skip','Skip is a hop')],'Sway means to move gently from side to side.'),
  M('9',2,'Which is a pair joined by and?','Sing and dance',[('Sing dance and','Wrong order'),('Dance sing','Missing and')],'Sing and dance.'),
  S('10',2,'Join eat and drink with the word and. Write the pair.',['eat and drink','Eat and drink'],'Eat and drink.'),
  M('11',3,'What do you need for a paper bag puppet?','A paper bag, colours and gum',[('A bucket of water','Not needed'),('A hammer','Not needed')],'A paper bag, colours, wool and gum are used.'),
  M('12',3,'Which word names a game for flying in the sky?','Kite flying',[('Ball bouncing','A ball stays low'),('Swinging','Swings move to and fro')],'A kite flies in the sky.')],
 keep=['and','kite'])
